/***
 * MARK: stageRunnerPolicy
 * @description Shared per-stage Runner allow/block list: the stage-side
 *   mirror of the Runner-side `operatorConfig` (a stage names which Runners
 *   may take it, instead of a Runner naming which work it serves). A policy
 *   is `{ mode: 'allow' | 'block', runners: [<runnerId>, ...] }` and is
 *   entirely optional — absent, malformed, or empty always means
 *   unrestricted, so legacy stages and unconfigured Runners keep working.
 *   Matching is by exact `runnerId` (trimmed, case kept): unknown or
 *   renamed Runner ids stay in the list and simply never match, so a rename
 *   can never silently open a compliance gate. The verdict helper is the
 *   single enforcement point — dispatch scan, direct claim, and integration
 *   lease routes all ask it, the same discipline as
 *   `operatorConfigVerdict`.
 ***/

/***
 * MARK: STAGE_RUNNER_POLICY_MODES
 * @description The two policy modes a stage runnerPolicy accepts: 'allow'
 *   (only the listed Runners may take the stage) and 'block' (every Runner
 *   except the listed ones may take it).
 * @example STAGE_RUNNER_POLICY_MODES.includes('allow') => true
 ***/
export const STAGE_RUNNER_POLICY_MODES = ["allow", "block"];

/***
 * MARK: normalizeStageRunnerPolicy
 * @description Normalizes a raw stage runnerPolicy into `{ mode, runners }`
 *   or `undefined` when the stage is unrestricted. Trims the mode
 *   (case-insensitive) and every Runner id, drops non-string and blank
 *   entries, and dedupes while keeping the first occurrence order. Absent,
 *   malformed, unknown-mode, or empty-after-cleaning input all normalize to
 *   `undefined` (fail open, never strand tasks on a mis-edit); unknown
 *   Runner ids are kept, never pruned, so a renamed Runner shows as stale
 *   in the UI instead of silently opening the gate.
 * @example normalizeStageRunnerPolicy({ mode: 'Allow', runners: [' r1 ', 'r1', 7] }) => { mode: 'allow', runners: ['r1'] }
 * @example normalizeStageRunnerPolicy(undefined) => undefined
 * @param {any} raw - Raw `stage.runnerPolicy` value.
 * @returns {{mode: string, runners: Array<string>}|undefined} Normalized policy, or undefined when unrestricted.
 ***/
export const normalizeStageRunnerPolicy = (raw) => {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
  const mode = typeof raw.mode === "string" ? raw.mode.trim().toLowerCase() : "";
  if (mode !== "allow" && mode !== "block") return undefined;
  if (!Array.isArray(raw.runners)) return undefined;
  const runners = [];
  const seen = new Set();
  for (const entry of raw.runners) {
    if (typeof entry !== "string") continue;
    const id = entry.trim();
    if (!id || seen.has(id)) continue;
    seen.add(id);
    runners.push(id);
  }
  if (runners.length === 0) return undefined;
  return { mode, runners };
};

/***
 * MARK: stageRunnerPolicyVerdict
 * @description Decides whether one Runner may take work from one stage
 *   under the stage's runnerPolicy. Accepts either the policy object itself
 *   or a stage carrying it as `.runnerPolicy` (the dispatch scan passes the
 *   requirement's attached policy, the claim routes pass the stage).
 *   Unrestricted stages allow every Runner; allow-mode refuses unlisted
 *   Runners with `RUNNER_NOT_ALLOWED`, block-mode refuses listed Runners
 *   with `RUNNER_BLOCKED`. Malformed input fails open to `MATCH` (legacy
 *   stages predate the field) and never throws, because this runs on hot
 *   claim paths.
 * @example stageRunnerPolicyVerdict({ mode: 'allow', runners: ['onsite-1'] }, 'cloud-2') => { ok: false, reason: 'RUNNER_NOT_ALLOWED' }
 * @example stageRunnerPolicyVerdict({ id: 's1' }, 'any-runner') => { ok: true, reason: 'MATCH' }
 * @param {Object|undefined} [stageOrPolicy] - Policy object or stage carrying `.runnerPolicy`.
 * @param {string} [runnerId] - Candidate Runner id.
 * @returns {Object} `{ ok, reason }` — reason is `MATCH` when allowed.
 ***/
export const stageRunnerPolicyVerdict = (stageOrPolicy, runnerId) => {
  const candidate =
    stageOrPolicy && typeof stageOrPolicy === "object" && !Array.isArray(stageOrPolicy)
      ? (stageOrPolicy.runnerPolicy !== undefined ? stageOrPolicy.runnerPolicy : stageOrPolicy)
      : undefined;
  const policy = normalizeStageRunnerPolicy(candidate);
  if (!policy) return { ok: true, reason: "MATCH" };
  if (typeof runnerId !== "string" || !runnerId.trim()) return { ok: true, reason: "MATCH" };
  const listed = policy.runners.includes(runnerId.trim());
  if (policy.mode === "allow") {
    return listed
      ? { ok: true, reason: "MATCH" }
      : { ok: false, reason: "RUNNER_NOT_ALLOWED" };
  }
  return listed
    ? { ok: false, reason: "RUNNER_BLOCKED" }
    : { ok: true, reason: "MATCH" };
};

/***
 * MARK: assertValidStageRunnerPolicies
 * @description Save-boundary helper: returns a 400-shaped error payload
 *   when any stage carries a malformed runnerPolicy, or null when every
 *   policy can save cleanly. Wrapping the shared validator lets route
 *   handlers stay one line (`if (err) return reply.status(400).send(err)`)
 *   instead of repeating the same 4-line problem check.
 * @example assertValidStageRunnerPolicies([{ runnerPolicy: { mode: 'only', runners: [] } }]) => { error: '...', details: [...] }
 * @example assertValidStageRunnerPolicies(undefined) => null
 * @param {Array|undefined} [stages] - Raw stages from a save payload (absent means no-op).
 * @returns {Object|null} `{ error, details }` for a 400, or null when clean.
 ***/
export const assertValidStageRunnerPolicies = (stages) => {
  if (stages === undefined || stages === null) return null;
  const problems = collectInvalidStageRunnerPolicies(stages);
  if (problems.length === 0) return null;
  return { error: "Invalid stage runnerPolicy entries", details: problems };
};

/***
 * MARK: collectInvalidStageRunnerPolicies
 * @description Save-time validation for stage runnerPolicy shapes: returns
 *   one problem per stage whose policy is present but malformed — a
 *   non-object policy, an unknown mode, or a non-array runners list. The
 *   stage create/update routes refuse such saves with 400 so a typo can
 *   never silently save as unrestricted (normalization alone would fail
 *   open). Unknown Runner ids are never flagged: a policy naming a deleted
 *   or renamed Runner stays closed and shows as stale in the UI.
 * @example collectInvalidStageRunnerPolicies([{ id: 's1', runnerPolicy: { mode: 'only', runners: [] } }]) => [{ index: 0, stageId: 's1', problem: 'UNKNOWN_MODE', mode: 'only' }]
 * @example collectInvalidStageRunnerPolicies([{ id: 's1' }]) => []
 * @param {Array|undefined} [stages] - Raw stages from a save payload.
 * @returns {Array<Object>} Problems as `{ index, stageId, problem, mode }` (empty when every policy saves cleanly).
 ***/
export const collectInvalidStageRunnerPolicies = (stages) => {
  if (!Array.isArray(stages)) return [];
  const problems = [];
  stages.forEach((stage, index) => {
    const raw = stage && typeof stage === "object" ? stage.runnerPolicy : undefined;
    if (raw === undefined || raw === null) return;
    const stageId = stage && typeof stage === "object" && stage.id !== undefined ? stage.id : null;
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
      problems.push({ index, stageId, problem: "POLICY_NOT_OBJECT", mode: null });
      return;
    }
    const mode = typeof raw.mode === "string" ? raw.mode.trim().toLowerCase() : "";
    if (mode !== "allow" && mode !== "block") {
      problems.push({
        index,
        stageId,
        problem: "UNKNOWN_MODE",
        mode: typeof raw.mode === "string" ? raw.mode : null,
      });
      return;
    }
    if (!Array.isArray(raw.runners)) {
      problems.push({ index, stageId, problem: "RUNNERS_NOT_ARRAY", mode });
    }
  });
  return problems;
};

import { normalizeStageTags } from "../../shared/stageTags.js";
import { normalizeStageRunnerPolicy } from "../../shared/stageRunnerPolicy.js";
import { DEFAULT_DEPLOY_COMMAND, isDeployCommand } from "./deployCommands.js";

/***
 * MARK: DEFAULT_STAGES
 * @description The default workflow pipeline for a new project.
 * Each stage carries an authoritative `type` discriminator:
 *   - 'agent'  -> automated execution by the AI (Bot/script stage)
 *   - 'human'  -> manual checkpoint requiring human approval/review
 *   - 'ci'     -> automated bash verification command (a deploy is a ci
 *                 stage whose command runs the deploy script)
 *   - 'merge'  -> git operations only (integrate the task branch into main)
 * The `failback` field describes where a task is routed if the stage fails.
 * A value of 'any' means the operator may route the task to any other stage.
 ***/
export const DEFAULT_STAGES = [
	{
		id: "1",
		name: "Idea",
		type: "agent",
		prompt: "Generate creative ideas.",
		paused: false,
		failback: "start",
	},
	{
		id: "2",
		name: "Technical Elab",
		type: "agent",
		prompt: "Elaborate on technical specs.",
		paused: false,
		failback: "previous",
	},
	{
		id: "3",
		name: "Plan",
		type: "agent",
		prompt: "Create a detailed plan.",
		paused: false,
		failback: "previous",
	},
	{
		id: "4",
		name: "Review Plan",
		type: "human",
		prompt: "Human review of the plan.",
		paused: false,
		failback: "previous",
	},
	{
		id: "5",
		name: "In Progress",
		type: "agent",
		prompt: "Executing the task.",
		paused: false,
		failback: "previous",
	},
	{
		id: "6",
		name: "Deploy",
		type: "ci",
		command: DEFAULT_DEPLOY_COMMAND,
		paused: false,
		failback: "previous",
	},
];

/***
 * MARK: normalizeStageType
 * @description Normalizes stage types to the authoritative types ('agent', 'human', 'ci', 'merge').
 * Legacy types are mapped: 'review' -> 'human', 'script' -> 'ci',
 * 'deploy' -> 'ci' (the deploy pipeline stage type was removed — a stage
 * whose command runs the deploy script is an ordinary ci stage with no
 * special runtime), 'custom'/other -> 'agent'.
 * @example normalizeStageType('review') => 'human'
 * @example normalizeStageType('deploy') => 'ci'
 * @param {string} [type]
 * @returns {'agent'|'human'|'ci'|'merge'}
 ***/
export function normalizeStageType(type) {
	if (!type || typeof type !== "string") return "agent";
	const lower = type.trim().toLowerCase();
	if (lower === "human" || lower === "review") return "human";
	if (lower === "ci" || lower === "script" || lower === "deploy") return "ci";
	if (lower === "merge") return "merge";
	if (lower === "agent") return "agent";
	return "agent";
}

/***
 * MARK: normalizeStageSkills
 * @description Normalizes a stage's optional `skills` attachment list. Unknown fields
 *   on each attachment pass through untouched (non-declarative tolerance); only the
 *   authoritative fields are coerced: `name` (trimmed), `mode` ('direct'|'option'),
 *   and `config` (plain object). Entries without a usable name are dropped.
 *   Returns `undefined` when `skills` is absent so legacy stages are untouched.
 * @example normalizeStageSkills([{ name: 'a', mode: 'OPTION', config: { x: 1 }, extra: true }])
 *   => [{ name: 'a', mode: 'option', config: { x: 1 }, extra: true }]
 * @param {Array|undefined} [skills]
 * @returns {Array<Object>|undefined}
 ***/
export function normalizeStageSkills(skills) {
	if (skills === undefined || skills === null) return undefined;
	if (!Array.isArray(skills)) return [];
	return skills
		.filter(
			(s) =>
				s && typeof s === "object" && typeof s.name === "string" && s.name.trim(),
		)
		.map((s) => {
			const normalized = { ...s, name: s.name.trim() };
			if (s.mode !== undefined) {
				normalized.mode =
					typeof s.mode === "string" && s.mode.trim().toLowerCase() === "option"
						? "option"
						: "direct";
			}
			if (s.config !== undefined) {
				normalized.config =
					s.config && typeof s.config === "object" && !Array.isArray(s.config)
						? s.config
						: {};
			}
			return normalized;
		});
}

/***
 * MARK: normalizeStage
 * @description Normalizes a single stage object ensuring stage type is strictly 'agent', 'human', or 'ci'.
 *   The optional per-stage `harness` override (blank/absent means "inherit the
 *   project harness") is trimmed; a blank or non-string value clears it
 *   (undefined) so persistence drops the key. The id itself is NOT validated
 *   here: an unknown harness warns visibly at session time and degrades to the
 *   project harness (see resolveHarnessForProject).
 *   CI stages additionally carry an optional `runOnBranch` mode ('task'
 *   default | 'primary' | 'custom', legacy 'main' maps to 'primary') and a
 *   `customBranch` name (trimmed; blank clears it). Legacy spellings
 *   `executionBranch`/`customExecutionBranch` are migrated to the canonical
 *   names and dropped so storage converges on the first save.
 *   Any stage may carry an optional `runnerPolicy`
 *   (`{ mode: 'allow' | 'block', runners: [...] }`) naming which Runners may
 *   take it; absent or empty means every Runner may (see
 *   normalizeStageRunnerPolicy).
 * @example normalizeStage({ id: '1', name: 'Test', type: 'script' }) => { id: '1', name: 'Test', type: 'ci' }
 * @example normalizeStage({ id: '1', harness: '  custom  ' }).harness => 'custom'
 * @param {Object} stage
 * @returns {Object}
 ***/
export function normalizeStage(stage) {
	if (!stage || typeof stage !== "object") return stage;
	// The removed `deploy` type folds into `ci` with no special runtime: a
	// legacy deploy stage keeps whatever command it carried (or no command,
	// like any other command-less ci stage) and runs as ordinary CI. The
	// default deploy command is never stamped — an explicit command is the
	// only thing that makes a stage run the deploy script.
	const normalized = {
		...stage,
		type: normalizeStageType(stage.type),
	};
	// Optional per-stage skills (additive): normalise only when present so legacy
	// stage objects round-trip byte-identically.
	if (stage.skills !== undefined) {
		const skills = normalizeStageSkills(stage.skills);
		if (skills !== undefined) normalized.skills = skills;
		else delete normalized.skills;
	}
	// Optional per-stage tags (additive): normalise only when present so legacy
	// stage objects round-trip byte-identically.
	if (stage.tags !== undefined) {
		const tags = normalizeStageTags(stage.tags);
		if (tags !== undefined) normalized.tags = tags;
		else delete normalized.tags;
	}
	// Optional per-stage Runner allow/block list (additive): normalise only
	// when present so legacy stage objects round-trip byte-identically. An
	// empty or malformed policy drops the key (unrestricted) so stored
	// stages stay clean; unknown modes are refused with 400 at the save
	// boundary before they ever reach here.
	if (stage.runnerPolicy !== undefined) {
		const runnerPolicy = normalizeStageRunnerPolicy(stage.runnerPolicy);
		if (runnerPolicy !== undefined) normalized.runnerPolicy = runnerPolicy;
		else delete normalized.runnerPolicy;
	}
	// Optional per-stage harness override (additive): same explicit-choice-only
	// rule as project.harness — blank clears it (undefined).
	if (stage.harness !== undefined) {
		normalized.harness =
			typeof stage.harness === "string" && stage.harness.trim()
				? stage.harness.trim()
				: undefined;
	}
	// Optional per-stage CI branch execution mode (additive):
	// 'task' (default, absent) | 'primary' (project default branch) | 'custom'.
	// The 'main' value and the executionBranch/customExecutionBranch key names
	// are legacy spellings from the same feature's first iteration — mapped
	// here so hand-edited or in-flight configs converge on the canonical
	// fields (the legacy keys are dropped, never re-saved).
	const RUN_ON_BRANCH = new Set(["task", "primary", "custom"]);
	const rawRunOnBranch =
		stage.runOnBranch !== undefined ? stage.runOnBranch : stage.executionBranch;
	if (rawRunOnBranch !== undefined) {
		const v =
			typeof rawRunOnBranch === "string" ? rawRunOnBranch.trim().toLowerCase() : "";
		const mapped = v === "main" ? "primary" : v;
		normalized.runOnBranch = RUN_ON_BRANCH.has(mapped) ? mapped : "task";
	}
	const rawCustomBranch =
		stage.customBranch !== undefined ? stage.customBranch : stage.customExecutionBranch;
	if (rawCustomBranch !== undefined) {
		normalized.customBranch =
			typeof rawCustomBranch === "string" && rawCustomBranch.trim()
				? rawCustomBranch.trim()
				: undefined;
	}
	delete normalized.executionBranch;
	delete normalized.customExecutionBranch;
	// Retired (was DA9): every command stage runs on a Runner — the backend
	// never executes stage commands, so no stage is ever host-only. Strip
	// any legacy hostOnly stamp so previously stored stages rejoin fleet
	// dispatch on the next normalization.
	delete normalized.hostOnly;
	return normalized;
}

/***
 * MARK: migrateMergeDeployStages
 * @description Migrates composite "Merge and deploy" stages — a merge stage
 *   that carries a command — into a git-only merge stage plus a dedicated
 *   command CI stage inserted immediately after it, in the same list and
 *   order. The merge stage only performs git operations now, so the command
 *   moves to its own ordinary ci stage: git failures and command failures
 *   can never mix again. The inserted stage keeps the recorded command
 *   verbatim (including a deploy-script command, which runs as ordinary CI
 *   with normal failback) and fails back to the merge stage ("previous").
 *
 *   Idempotent: a merge stage without a command is left untouched, and the
 *   inserted deploy stage reuses the deterministic id `<mergeId>-deploy`, so
 *   re-running the migration (every project load/save normalizes again)
 *   never duplicates it. A non-deploy post-merge command is dropped from the
 *   merge stage without an inserted stage (deprecated: see DEPRECATIONS.md).
 * @example migrateMergeDeployStages([{ id: 'm', type: 'merge', command: './deploy.sh --prod' }])
 *   => [{ id: 'm', type: 'merge' }, { id: 'm-deploy', type: 'ci', command: './deploy.sh --prod' }]
 * @param {Array<Object>} [stages] - Already type-normalized stages.
 * @returns {Array<Object>} The migrated stage list (same order + inserted deploy stages).
 ***/
export function migrateMergeDeployStages(stages) {
	if (!Array.isArray(stages)) return [];
	const existingIds = new Set(
		stages.filter((s) => s && typeof s === "object").map((s) => String(s.id)),
	);
	const out = [];
	for (const stage of stages) {
		const isMergeStage =
			stage &&
			typeof stage === "object" &&
			String(stage.type || "").toLowerCase() === "merge";
		const command =
			isMergeStage &&
			((typeof stage.command === "string" && stage.command.trim()) ||
				(typeof stage.script === "string" && stage.script.trim()))
				? stage.command || stage.script
				: "";
		if (!isMergeStage || !command) {
			out.push(stage);
			continue;
		}
		// Strip the command: a merge stage is git-only and ignores commands.
		const mergeStage = { ...stage };
		delete mergeStage.command;
		delete mergeStage.script;
		// A name that advertised the composite ("Merge and deploy") must
		// not lie about the now git-only stage.
		const name = String(mergeStage.name || "");
		if (/merge/i.test(name) && /deploy/i.test(name)) {
			mergeStage.name = "Merge";
		}
		out.push(mergeStage);
		if (!isDeployCommand(command)) continue; // dropped, deprecated
		const deployStageId = `${String(mergeStage.id || "merge")}-deploy`;
		if (existingIds.has(deployStageId)) continue; // already migrated
		out.push({
			id: deployStageId,
			name: "Deploy",
			type: "ci",
			command,
			paused: false,
			failback: "previous",
		});
	}
	return out;
}

/***
 * MARK: normalizeStages
 * @description Normalizes an array of stage objects ensuring legacy types
 *   are migrated, then migrates composite merge-and-command stages into a
 *   git-only merge stage plus a dedicated command CI stage (see
 *   migrateMergeDeployStages).
 * @example normalizeStages([{ type: 'review' }]) => [{ type: 'human' }]
 * @example normalizeStages([{ type: 'merge', command: './deploy.sh --prod' }]).length => 2
 * @param {Array<Object>} [stages]
 * @returns {Array<Object>}
 ***/
export function normalizeStages(stages) {
	if (!Array.isArray(stages)) return [];
	return migrateMergeDeployStages(stages.map(normalizeStage));
}

import { InfoTooltip } from '../common/InfoTooltip';
import { SelectDropdown } from '../common/SelectDropdown';
import { StageTypeConfig } from './StageTypeConfig';
import { StageTagEditor } from './StageTagEditor';
import { StageRunnerPolicyEditor } from './StageRunnerPolicyEditor';
import { availableStageTags, normalizeStageTags } from '../../../../shared/stageTags.js';

/***
 * MARK: StageSettingsDrawer
 * @description In-column full-height expandable stage settings drawer
 *   extracted from WorkflowCanvas (#9, #10, #11, #42): toggle button, drawer
 *   shell (header, name, description, type selector), per-type fields via
 *   `StageTypeConfig`, pause/fallback section and footer (delete + done).
 * @example <StageSettingsDrawer stage={stage} stages={stages} isSettingsExpanded={open} ... />
 ***/
export function StageSettingsDrawer({
  stage,
  stages,
  isSettingsExpanded,
  onToggleSettings,
  onCloseSettings,
  onSaveAndClose,
  onUpdateStage,
  onTypeChange,
  activeProjectId,
  saveStages,
  pendingStageAction,
  removeStageAndSave,
  typeConfigProps,
}) {
  return (
    <div className="border-t border-border-standard bg-surface-container/60 shrink-0">
      <button
        type="button"
        onClick={onToggleSettings}
        aria-expanded={isSettingsExpanded}
        aria-label={`Configure stage ${stage.name}`}
        className={`w-full py-2 px-3 text-[10px] font-label-caps uppercase tracking-wider flex items-center justify-between transition-colors cursor-pointer select-none ${
          isSettingsExpanded
            ? 'bg-ochre/20 text-[#ffe0b2] font-bold border-b border-ochre/30'
            : 'text-text-muted hover:text-[#ffe0b2] hover:bg-surface-container'
        }`}
      >
        <span className="flex items-center gap-1.5 font-bold">
          <span>⚙️</span>
          <span>Stage Settings</span>
        </span>
        <span className="text-[9px] font-mono font-bold">
          {isSettingsExpanded ? '▼ CLOSE' : '▲ EDIT'}
        </span>
      </button>

      {isSettingsExpanded && (
        <div className="absolute inset-0 z-20 flex flex-col bg-surface-deep border rounded-sm overflow-hidden h-full animate-in fade-in duration-200">
          {/* Full-Height Drawer Header */}
          <header className="p-3 bg-surface-container border-b border-border-standard flex items-center justify-between shrink-0">
            <div className="flex items-center gap-1.5 min-w-0">
              <span className="text-ochre">⚙️</span>
              <span className="font-label-caps text-xs font-bold uppercase tracking-wider text-on-surface truncate">
                Configure {stage.name}
              </span>
            </div>
            <button
              type="button"
              onClick={onCloseSettings}
              aria-label={`Close settings for ${stage.name}`}
              className="p-1 min-w-[44px] min-h-[44px] text-text-muted hover:text-on-surface hover:bg-surface-container-high rounded transition-colors cursor-pointer"
            >
              ✕
            </button>
          </header>

          {/* Full-Height Drawer Body */}
          <div className="flex-1 p-3 space-y-4 overflow-y-auto custom-scrollbar">
            {/* Stage Name */}
            <div className="space-y-1">
              <span className="text-[9px] font-bold uppercase text-text-muted tracking-wider block">
                Stage Name
              </span>
              <input
                type="text"
                aria-label={`Stage name for ${stage.name}`}
                value={stage.name}
                onChange={(e) => {
                  onUpdateStage?.(stage.id, { name: e.target.value });
                }}
                className="w-full p-2 bg-surface-container border border-border-standard rounded-sm text-xs font-bold uppercase text-on-surface outline-none focus:border-primary"
              />
            </div>

            {/* Stage Description */}
            <div className="space-y-1">
              <span className="text-[9px] font-bold uppercase text-text-muted tracking-wider block">
                Description / Sublabel
              </span>
              <input
                type="text"
                aria-label={`Description for ${stage.name}`}
                value={stage.description || ''}
                onChange={(e) => {
                  onUpdateStage?.(stage.id, { description: e.target.value });
                }}
                placeholder="Stage purpose"
                className="w-full p-2 bg-surface-container border border-border-standard rounded-sm text-[11px] text-on-surface outline-none focus:border-primary"
              />
            </div>
            {/* Stage Tags — chip editor; tags filter the board (see the
                toolbar tag filter) and round-trip through the backend. */}
            <StageTagEditor
              value={Array.isArray(stage.tags) ? stage.tags : []}
              availableTags={availableStageTags(stages)}
              stageName={stage.name}
              onChange={(tags) => {
                onUpdateStage?.(stage.id, { tags: normalizeStageTags(tags) ?? [] });
              }}
            />
            <p className="text-[10px] text-text-muted font-mono">
              Tags let you filter the board down to a subset of stages (e.g. split a
              long pipeline between PO and Dev views).
            </p>

            {/* Stage Type Selector */}
            <div className="space-y-1">
              <span className="text-[9px] font-bold uppercase text-text-muted tracking-wider block">
                Stage Type
              </span>
              <SelectDropdown
                ariaLabel={`Stage type for ${stage.name}`}
                className="block w-full"
